head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > allowChar]<br/>입력이 가능한 문자의 집합을 정규식의 문자클래스 형식으로 설정합니다.",
    "validation" : [
        "정규식의 문자클래스 형식으로 입력이 가능한 문자 집합을 설정합니다.",        
        "정규식의 문자클래스에서 특수문자로 처리되는 ']', '-', '\' 등의 문자는 이스케이프 처리하여 설정해야 합니다.",
        "설정값은 정규식의 문자클래스('[...]' 처리)에 반영되어 입력이 가능한 문자를 찾는데 사용됩니다.",
        "한글과 같은 다국어 문자와 붙여넣기로 입력된 값은 컴포넌트에서 포커스가 해제될 때 처리되며 oninputinvalid 이벤트는 발생하지 않습니다.",
        "ignoreChar 속성에 같은 문자가 설정된 경우 해당 문자는 입력 되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}

let strValue = "azAZ123가나다~!@#$%^&*()_+-=\[]{},./;':\""


// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue(strValue);
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

